#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    char *name;
    int score;
    struct Node *next;
} Node;

Node *add_last(Node *head, char *name, int score) {
    /* ↓ 在这儿写：租一节、把名字和分数放进去、把这一节记着的下一节写成 NULL；
       链子还空着就把它交回去当新的头，否则从头走到最后一节，把新节挂在它后头。 */

    return head;
}

void print_all(Node *head) {
    for (Node *p = head; p != NULL; p = p->next) {
        printf("%s：%d 分\n", p->name, p->score);
    }
}

int main(void) {
    Node *head = NULL;
    head = add_last(head, "小橘", 90);
    head = add_last(head, "小白", 85);
    head = add_last(head, "阿花", 95);
    print_all(head);
    return 0;
}

