#include <stdlib.h>

typedef struct Node {
    char *name;
    int score;
    struct Node *next;
} Node;

Node *add_last(Node *head, char *name, int score) {
    Node *fresh = malloc(sizeof(Node));
    if (fresh == NULL) {
        return head;
    }
    fresh->name = name;
    fresh->score = score;
    fresh->next = NULL;
    if (head == NULL) {
        return fresh;
    }
    Node *p = head;
    while (p->next != NULL) {
        p = p->next;
    }
    p->next = fresh;
    return head;
}

void save_to_file(Node *head, const char *path) {
    FILE *fp = fopen(path, "w");
    if (fp == NULL) {
        printf("档案开不了喵\n");
        return;
    }
    /* ↓ 在这儿写：走链子，把每一节写成一个「名字 分数」的行（行尾记得换行） */

    fclose(fp);
}

int main(void) {
    Node *head = NULL;
    head = add_last(head, "大黄", 88);
    head = add_last(head, "小白", 92);
    head = add_last(head, "阿花", 95);
    save_to_file(head, "scores.txt");

    FILE *fp = fopen("scores.txt", "r");
    if (fp == NULL) {
        printf("档案丢了喵\n");
        return 0;
    }
    char name[16];
    int score;
    int n = 0;
    while (fscanf(fp, "%15s %d", name, &score) == 2) {
        n++;
        printf("第 %d 位：%s %d 分\n", n, name, score);
    }
    fclose(fp);
    printf("一共 %d 位\n", n);
    return 0;
}

